<?php
include('../assets/head.php');
require_once __DIR__ . '/lib/page.php';
$con = sat_db();
sat_page_inicio('contabilidad', 'Contabilidad automática');
$id=(int)($_GET['id_empresa']??0);$fi=$_GET['fecha_inicial']??date('Y-m-01');$ff=$_GET['fecha_final']??date('Y-m-t');$msg=$_GET['msg']??'';
if($id>0) AccountingService::bootstrapEmpresa($con,$id);
$empresas=mysqli_query($con,"SELECT id_empresa,rfc,razon_social FROM sat_empresas WHERE activo=1 ORDER BY razon_social");
$where=" WHERE p.fecha BETWEEN '".mysqli_real_escape_string($con,$fi)."' AND '".mysqli_real_escape_string($con,$ff)."' ";if($id>0)$where.=" AND p.id_empresa=$id ";
$polizas=mysqli_query($con,"SELECT p.*,e.razon_social,c.tipo_relacion_empresa,c.nombre_emisor,c.nombre_receptor,ABS(p.total_cargos-p.total_abonos) diferencia FROM sat_polizas p JOIN sat_empresas e ON e.id_empresa=p.id_empresa JOIN sat_cfdi c ON c.id_cfdi=p.id_cfdi $where ORDER BY p.fecha DESC,p.id_poliza DESC LIMIT 300");
$sum=mysqli_fetch_assoc(mysqli_query($con,"SELECT COUNT(*) total,SUM(estatus='CONTABILIZADA') ok,SUM(estatus='REVISAR') revisar,COALESCE(SUM(total_cargos),0)cargos,COALESCE(SUM(total_abonos),0)abonos FROM sat_polizas p $where"));

?>
<?php if($msg!==''):?><div class="alert alert-info"><?=e($msg)?></div><?php endif?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h3 class="mb-1">Contabilidad automática</h3><div class="text-muted">Pólizas generadas desde CFDI, impuestos separados y aprendizaje por diferencias.</div></div><div><?php if($id>0):?><a href="configuracion_contable.php?id_empresa=<?=$id?>" class="btn btn-outline-dark">Configuración de impuestos</a> <a href="cuentas_contables.php?id_empresa=<?=$id?>" class="btn btn-outline-primary">Cuentas</a> <a href="reglas_contables.php?id_empresa=<?=$id?>" class="btn btn-primary">Reglas / aprendizaje</a><?php endif?></div></div>
<div class="sat-card p-4 mb-4"><form class="row g-3"><div class="col-md-4"><label class="form-label">Empresa</label><select class="form-control" name="id_empresa" required><option value="0">Seleccione</option><?php while($e=mysqli_fetch_assoc($empresas)):?><option value="<?=$e['id_empresa']?>" <?=$id==$e['id_empresa']?'selected':''?>><?=e($e['rfc'].' - '.$e['razon_social'])?></option><?php endwhile?></select></div><div class="col-md-3"><label class="form-label">Desde</label><input type="date" class="form-control" name="fecha_inicial" value="<?=e($fi)?>"></div><div class="col-md-3"><label class="form-label">Hasta</label><input type="date" class="form-control" name="fecha_final" value="<?=e($ff)?>"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-dark w-100">Consultar</button></div></form><?php if($id>0):?><div class="mt-3 d-flex gap-2 flex-wrap"><a class="btn btn-success" href="php/postContabilizarPendientes.php?id_empresa=<?=$id?>&fecha_inicial=<?=urlencode($fi)?>&fecha_final=<?=urlencode($ff)?>">Contabilizar CFDI pendientes</a><a class="btn btn-warning" href="php/postRecalcularPolizas.php?id_empresa=<?=$id?>&fecha_inicial=<?=urlencode($fi)?>&fecha_final=<?=urlencode($ff)?>" onclick="return confirm('¿Recalcular todas las pólizas del periodo con las reglas e impuestos actuales?')">Recalcular pólizas del periodo</a></div><?php endif?></div>
<div class="row g-3 mb-4"><div class="col-md-3"><div class="sat-card p-3"><small class="text-muted">Pólizas</small><h3><?=number_format((int)($sum['total']??0))?></h3></div></div><div class="col-md-3"><div class="sat-card p-3"><small class="text-muted">Contabilizadas</small><h3><?=number_format((int)($sum['ok']??0))?></h3></div></div><div class="col-md-3"><div class="sat-card p-3"><small class="text-muted">Por revisar</small><h3><?=number_format((int)($sum['revisar']??0))?></h3></div></div><div class="col-md-3"><div class="sat-card p-3"><small class="text-muted">Diferencia global Debe/Haber</small><h3>$<?=number_format(abs((float)($sum['cargos']??0)-(float)($sum['abonos']??0)),2)?></h3></div></div></div>
<div class="sat-card p-4"><div class="table-responsive"><table class="sat-tabla align-middle"><thead><tr><th>Fecha</th><th>Empresa</th><th>Tipo</th><th>UUID</th><th>Concepto</th><th class="text-end">Debe</th><th class="text-end">Haber</th><th class="text-end">Diferencia</th><th>Estado</th><th></th></tr></thead><tbody><?php if($polizas)while($p=mysqli_fetch_assoc($polizas)): $dif=(float)$p['diferencia'];?><tr><td><?=e($p['fecha'])?></td><td><?=e($p['razon_social'])?></td><td><?=e($p['tipo_poliza'])?></td><td><small><?=e($p['uuid'])?></small></td><td><?=e($p['concepto'])?><br><small class="text-danger"><?=e($p['mensaje_revision'])?></small></td><td class="text-end">$<?=number_format($p['total_cargos'],2)?></td><td class="text-end">$<?=number_format($p['total_abonos'],2)?></td><td class="text-end fw-bold <?=$dif>0.02?'text-danger':'text-success'?>">$<?=number_format($dif,2)?></td><td><span class="<?=$p['estatus']==='CONTABILIZADA'?'sat-badge ok':'sat-badge warn'?>"><?=e($p['estatus'])?></span></td><td><a class="btn btn-sm btn-outline-primary" href="poliza.php?id_poliza=<?=$p['id_poliza']?>">Ver / resolver</a></td></tr><?php endwhile?></tbody></table></div></div>
<?php sat_page_fin(); include('../assets/footer.php'); ?>
